// clients/teams-bot/src/intake/mention.ts
function stripMentions(rawText, entities, botId) {
  let text2 = rawText;
  let strippedByEntity = false;
  let sawMentionEntity = false;
  for (const entity of entities ?? []) {
    if (entity.type.toLowerCase() !== "mention")
      continue;
    if (entity.text === undefined || entity.text === "")
      continue;
    sawMentionEntity = true;
    if (!text2.includes(entity.text))
      continue;
    const addressesBot = botId === undefined || entity.mentioned?.id === undefined || entity.mentioned.id === botId;
    if (addressesBot) {
      text2 = text2.split(entity.text).join(" ");
    } else {
      text2 = text2.split(entity.text).join(entity.mentioned?.name ?? " ");
    }
    strippedByEntity = true;
  }
  let usedFallback = false;
  if (!sawMentionEntity) {
    const beforeFallback = text2;
    text2 = text2.replace(/<at>[^<]*<\/at>/gi, " ");
    usedFallback = text2 !== beforeFallback;
  }
  const removedSomething = strippedByEntity || usedFallback;
  return {
    text: removedSomething ? text2.replace(/[ \t]{2,}/g, " ").trim() : rawText,
    strippedByEntity,
    usedFallback
  };
}

